__EMBED["core/i18n"] = function()
local M = {}

M.Languages = {
    { Code = "en", Name = "English" },
    { Code = "pt", Name = "Português" },
    { Code = "es", Name = "Español" },
    { Code = "ru", Name = "Русский" },
}

function M.new(ctx)
    ctx.Languages = M.Languages
    local packs = { en = {}, pt = {}, es = {}, ru = {} }
    local current = "en"

    function ctx.addStrings(code, strings)
        local pack = packs[code]
        if not pack then
            return
        end
        for key, value in pairs(strings) do
            pack[key] = value
        end
    end

    function ctx.L(key, ...)
        local pack = packs[current]
        local text = (pack and pack[key]) or packs.en[key] or key
        if select("#", ...) > 0 then
            local ok, formatted = pcall(string.format, text, ...)
            if ok then
                return formatted
            end
        end
        return text
    end

    function ctx.describe(key)
        local text = ctx.L(key .. "_d")
        if text == key .. "_d" then
            return nil
        end
        return text
    end

    function ctx.setLanguage(code)
        if not packs[code] then
            return false
        end
        current = code
        return true
    end

    function ctx.getLanguage()
        return current
    end
end

return M
end

__EMBED["core/keysystem"] = function()
local M = {}

local LOCAL_LOGO = "Dominant/Assets/logo.png"

-- The loader saves the GitHub logo here; the key window uses it so both look the same.
local function localLogo()
    local ok, asset = pcall(function()
        local getter = getcustomasset or getsynasset
        if type(getter) == "function" and type(isfile) == "function" and isfile(LOCAL_LOGO) then
            return getter(LOCAL_LOGO)
        end
        return nil
    end)
    if ok and type(asset) == "string" then
        return asset
    end
    return nil
end

function M.run(config, supportedIds, onSuccess, status, modules)
    local env = getgenv and getgenv() or _G
    if env.DominantSkipKey == true then
        onSuccess()
        return
    end

    local ok, Ophyn = false, nil
    if modules then
        ok, Ophyn = pcall(function()
            return modules:require("vendor/ophyn")
        end)
    end
    if not ok or type(Ophyn) ~= "table" or type(Ophyn.new) ~= "function" then
        ok, Ophyn = pcall(function()
            return loadstring(game:HttpGet(config.OphynUrl))()
        end)
    end
    if not ok or type(Ophyn) ~= "table" or type(Ophyn.new) ~= "function" then
        status("Key system unavailable")
        onSuccess()
        return
    end

    local supported = {}
    for _, id in ipairs(supportedIds) do
        supported[id] = true
    end
    supported[game.PlaceId] = true

    local started = false
    local function accept()
        if started then
            return
        end
        started = true
        onSuccess()
    end

    local attempt, attemptError = pcall(function()
        Ophyn.new({
            Title = config.Title,
            Description = config.Description,
            Logo = localLogo() or config.Logo,
            Theme = config.KeyTheme or "Dominant",
            Folder = config.Folder,
            getkey = false,
            Intro = "false",
            startintrosize = 80,
            squareintrotime = 1.2,
            squarecontorn = "true",
            Changelogocolor = false,
            Changeiconscolor = false,
            ChangeTheme = "true",
            discordlink = config.Discord,
            website_link = config.Website,
            Discord = "true",
            Website = "true",
            Informations = "true",
            Keyless = { enabled = false },
            NotifStyle = "1",
            TabsStyle = "1",
            SupportedGames = supported,
            KeySystem = {
                Key = config.Keys,
                SaveKey = config.SaveKey,
            },
            Callback = function()
                accept()
            end,
        })
    end)

    if not attempt then
        status("Key system failed: " .. tostring(attemptError))
        accept()
    end
end

return M
end

__EMBED["core/modules"] = function()
local Modules = {}
Modules.__index = Modules

local B64 = "ABCDEFGHIJKLMNOPQRSTUVWXYZabcdefghijklmnopqrstuvwxyz0123456789+/"
local LOOKUP = {}
for i = 1, #B64 do
    LOOKUP[string.byte(B64, i)] = i - 1
end

local function decodeBase64(data)
    data = string.gsub(data, "[^%w%+/=]", "")
    local out = {}
    for i = 1, #data, 4 do
        local a, b, c, d = string.byte(data, i, i + 3)
        local n = (LOOKUP[a] or 0) * 262144 + (LOOKUP[b] or 0) * 4096 + (LOOKUP[c] or 0) * 64 + (LOOKUP[d] or 0)
        out[#out + 1] = string.char(math.floor(n / 65536) % 256)
        if c ~= 61 then
            out[#out + 1] = string.char(math.floor(n / 256) % 256)
        end
        if d ~= 61 then
            out[#out + 1] = string.char(n % 256)
        end
    end
    return table.concat(out)
end

Modules.decodeBase64 = decodeBase64

function Modules.new(baseUrl)
    return setmetatable({ base = baseUrl, cache = {} }, Modules)
end

function Modules:asset(file)
    local encoded = self.embeddedAssets and self.embeddedAssets[file]
    if type(encoded) ~= "string" then
        return nil
    end
    return decodeBase64(encoded)
end

function Modules:fetch(path)
    if self.embedded and self.embedded[path] then
        return self.embedded[path]
    end
    local url = self.base .. path .. ".lua"
    local ok, body = pcall(game.HttpGet, game, url)
    if not ok or type(body) ~= "string" or #body < 10 then
        error("could not download " .. url)
    end
    local chunk, compileError = loadstring(body)
    if not chunk then
        error("could not compile " .. path .. ": " .. tostring(compileError))
    end
    return chunk
end

function Modules:require(path)
    local cached = self.cache[path]
    if cached ~= nil then
        return cached
    end
    local result = self:fetch(path)()
    if result == nil then
        error("module " .. path .. " returned nothing")
    end
    self.cache[path] = result
    return result
end

return Modules
end

__EMBED["core/ui"] = function()
local M = {}

local function keyFromName(name)
    local ok, key = pcall(function()
        return Enum.KeyCode[name]
    end)
    if ok and key then
        return key
    end
    return Enum.KeyCode.Unknown
end

function M.new(ctx)
    local ui = {}

    function ui.section(tab, key, icon)
        tab:AddSection(ctx.L(key), icon)
    end

    function ui.toggle(tab, key, icon)
        tab:AddToggle({
            Text = ctx.L(key),
            Description = ctx.describe(key),
            Icon = icon,
            Flag = key,
            Default = ctx.cfg[key],
            Callback = function(value)
                ctx.set(key, value)
            end,
        })
    end

    function ui.labelToggle(tab, key, text, description, icon)
        tab:AddToggle({
            Text = text,
            Description = description,
            Icon = icon,
            Flag = key,
            Default = ctx.cfg[key],
            Callback = function(value)
                ctx.set(key, value)
            end,
        })
    end

    function ui.slider(tab, key, minimum, maximum, step, icon, suffix)
        tab:AddSlider({
            Text = ctx.L(key),
            Description = ctx.describe(key),
            Icon = icon,
            Flag = key,
            Min = minimum,
            Max = maximum,
            Default = ctx.cfg[key],
            Increment = step,
            Suffix = suffix,
            Callback = function(value)
                ctx.set(key, value)
            end,
        })
    end

    function ui.dropdown(tab, key, options, icon, current, onChange)
        tab:AddDropdown({
            Text = ctx.L(key),
            Description = ctx.describe(key),
            Icon = icon,
            Options = options,
            Default = current or ctx.cfg[key],
            Flag = key,
            Callback = function(value)
                if type(value) == "table" then
                    value = value[1]
                end
                if onChange then
                    onChange(value)
                else
                    ctx.set(key, value)
                end
            end,
        })
    end

    function ui.number(tab, key, icon, minimum)
        local pending = 0
        tab:AddTextbox({
            Text = ctx.L(key),
            Description = ctx.describe(key),
            Icon = icon,
            Placeholder = ctx.L("number_hint"),
            Default = tostring(ctx.cfg[key]),
            Callback = function(text, enter)
                local cleaned = (tostring(text or ""):gsub(",", "."):gsub("[^%d%.%-]", ""))
                local value = tonumber(cleaned)
                if not value then
                    return
                end
                value = math.max(minimum or 1, value)
                ctx.set(key, value)
                pending += 1
                local ticket = pending
                if enter then
                    ctx.notify(ctx.L("n_value_set", ctx.L(key), tostring(value)), "info", 2)
                else
                    task.delay(0.35, function()
                        if ticket == pending then
                            ctx.notify(ctx.L("n_value_set", ctx.L(key), tostring(value)), "info", 2)
                        end
                    end)
                end
            end,
        })
    end

    function ui.color(tab, key, icon)
        tab:AddColorPicker({
            Text = ctx.L(key),
            Icon = icon,
            Default = ctx.cfg[key],
            Callback = function(color)
                ctx.set(key, color)
            end,
        })
    end

    function ui.button(tab, key, icon, callback)
        tab:AddButton({
            Text = ctx.L(key),
            Description = ctx.describe(key),
            Icon = icon,
            Callback = callback,
        })
    end

    function ui.keybind(tab, labelKey, icon, currentName, onPress, onChange)
        tab:AddKeybind({
            Text = ctx.L(labelKey),
            Description = ctx.describe(labelKey),
            Icon = icon,
            Default = keyFromName(currentName),
            Callback = function(key, kind)
                if kind == "press" then
                    if onPress then
                        onPress()
                    end
                elseif typeof(key) == "EnumItem" then
                    if onChange then
                        onChange(key.Name)
                    end
                end
            end,
        })
    end

    return ui
end

return M
end

__EMBED["core/vind"] = function()
local M = {}

local function fetchRemote(config)
    local ok, body = pcall(game.HttpGet, game, config.VindUrl)
    if not ok or type(body) ~= "string" or #body < 100 then
        return nil, "could not download Vind UI"
    end
    local chunk, compileError = loadstring(body)
    if not chunk then
        return nil, compileError
    end
    local okRun, library = pcall(chunk)
    if not okRun or type(library) ~= "table" then
        return nil, library
    end
    return library
end

function M.load(config, uiTheme, modules)
    local library, loadError = nil, nil
    if modules then
        local okEmbedded, embedded = pcall(function()
            return modules:require("vendor/vind")
        end)
        if okEmbedded and type(embedded) == "table" then
            library = embedded
        else
            loadError = embedded
        end
    end
    if not library then
        library, loadError = fetchRemote(config)
    end
    if not library then
        return nil, loadError
    end
    pcall(function()
        library:SetTheme(config.Theme)
    end)
    if type(uiTheme) == "table" and type(library.Theme) == "table" then
        local P = uiTheme.palette
        local overrides = {
            Background = P.bg, Surface = P.input, Card = P.card, Text = P.text,
            TextDim = P.muted, Accent = P.accent, Outline = P.stroke, Border = P.stroke,
            Button = P.btn2, ButtonHover = P.btn2Hover, Input = P.input,
            Placeholder = P.muted, Stroke = P.stroke,
        }
        for key, value in pairs(overrides) do
            library.Theme[key] = value
        end
    end
    pcall(function()
        library:PreloadIcons({ "Lucide", "Material", "Phosphor", "SF" })
    end)
    pcall(function()
        library:SetScaleRange(0.75, 1.35)
    end)
    return library
end

return M
end

