        Surface = Color3.fromRGB(24, 24, 24),
        Card = Color3.fromRGB(30, 30, 34),
        Text = Color3.fromRGB(240, 240, 240),
        Dim = Color3.fromRGB(150, 150, 155),
        Accent = Color3.fromRGB(255, 90, 90),
        Border = Color3.fromRGB(255, 255, 255),
