    title.Position = UDim2.fromOffset(14, 6)
    title.Size = UDim2.new(1, -50, 0, 16)
    title.Font = Enum.Font.GothamBold
    title.TextSize = 14
    title.TextXAlignment = Enum.TextXAlignment.Left
    title.TextColor3 = theme.Text
    title.Text = L("bg_browse")
