local instance

function M.open(ctx)
    if not instance then
        local dominant = ctx.modules:require("shared/ui_theme").make(ctx)
        local ok, result = pcall(build, dominant)
        if not ok then
            ctx.warn("[Dominant] Avatar editor failed: " .. tostring(result))
            ctx.notify("Avatar editor failed to start", "error", 4)
            return
        end
        instance = result
    end
    instance.open()
end

return M
end

__EMBED["shared/features/background"] = function()
local M = {}

local EXTENSIONS = { png = true, jpg = true, jpeg = true, gif = true }

local function root(ctx)
    return ctx.config.Folder .. "/Backgrounds"
end

local function basename(path)
    return tostring(path or ""):gsub("\\", "/"):match("([^/]+)$") or tostring(path)
end

local function isImage(path)
    local ext = string.lower(tostring(path or "")):match("%.([%w]+)$")
    return ext ~= nil and EXTENSIONS[ext] == true
end

local function isGif(path)
    return string.lower(tostring(path or "")):match("%.gif$") ~= nil
end

function M.resolve(ctx, path)
    return ctx.assets.resolve(path)
end

function M.tree(ctx, folder, depth)
    depth = depth or 0
    local nodes = {}
    if not ctx.caps.files or type(listfiles) ~= "function" then
        return nodes
    end
    local ok, entries = pcall(listfiles, folder or root(ctx))
    if not ok or type(entries) ~= "table" then
        return nodes
    end
    table.sort(entries)
    for _, entry in ipairs(entries) do
        local isDir = false
        if type(isfolder) == "function" then
            local okFolder, result = pcall(isfolder, entry)
            isDir = okFolder and result == true
        end
        if isDir then
            if depth < 8 then
                for _, child in ipairs(M.tree(ctx, entry, depth + 1)) do
                    table.insert(nodes, child)
                end
            end
        elseif isImage(entry) then
            table.insert(nodes, { Path = entry, Name = basename(entry), Kind = "file", Gif = isGif(entry) })
        end
    end
    return nodes
end

local function setImage(ctx, asset)
    local window = ctx.window
    if not window then
        return false
    end
    local transparency = math.clamp(tonumber(ctx.cfg.bg_transparency) or 0.45, 0, 1)
    local windowTransparency = math.clamp(tonumber(ctx.cfg.bg_window_transparency) or 0.35, 0, 1)
    pcall(function()
        window:SetBackground({ Image = asset or "", Transparency = transparency })
    end)
    pcall(function()
        window:SetBackgroundTransparency(windowTransparency)
    end)
    return true
end

local function collectFrames(ctx, gifPath)
    local stem = basename(gifPath):gsub("%.[^%.]+$", "")
    local candidates = {
        root(ctx) .. "/frames/" .. stem,
        root(ctx) .. "/" .. stem .. "_frames",
        root(ctx) .. "/" .. stem,
    }
    local frames = {}
    for _, folder in ipairs(candidates) do
        local okDir, isDir = pcall(isfolder, folder)
        if okDir and isDir then
            local okList, entries = pcall(listfiles, folder)
            if okList and type(entries) == "table" then
                local ordered = {}
                for _, entry in ipairs(entries) do
                    local lower = string.lower(tostring(entry))
                    if lower:match("%.png$") or lower:match("%.jpe?g$") then
                        table.insert(ordered, entry)
                    end
                end
                table.sort(ordered)
                for _, entry in ipairs(ordered) do
                    local asset = M.resolve(ctx, entry)
                    if asset then
                        table.insert(frames, asset)
                    end
                end
                if #frames > 0 then
                    return frames
                end
            end
        end
    end
    return frames
end

local function playGif(ctx, frames, fps)
    local index = 1
    ctx.startLoop("background_gif", 1 / fps, function()
        local window = ctx.window
        if window and window._BackgroundImage then
            window._BackgroundImage.Image = frames[index]
        end
        index += 1
        if index > #frames then
            index = 1
        end
    end)
end

function M.clear(ctx)
    ctx.stopLoop("background_gif")
    if ctx.window then
        pcall(function()
            ctx.window:SetBackground({ Image = "" })
        end)
    end
    return true
end

function M.apply(ctx, path)
    ctx.stopLoop("background_gif")
    if not path or path == "" then
        local asset = ctx.assets.get("default_background")
        if not asset then
            ctx.notify(ctx.L("bg_failed"), "error", 4)
            return false
        end
        setImage(ctx, asset)
        return true
    end
    if isGif(path) then
        local frames = collectFrames(ctx, path)
        local first = M.resolve(ctx, path) or frames[1]
        if not first then
            ctx.notify(ctx.L("bg_failed"), "error", 4)
            return false
        end
        setImage(ctx, first)
        if #frames > 1 then
            playGif(ctx, frames, 12)
        end
        return true
    end
    local asset = M.resolve(ctx, path)
    if not asset then
        ctx.notify(ctx.L("bg_failed"), "error", 4)
        return false
    end
    setImage(ctx, asset)
    return true
end

function M.feat(ctx)
    if ctx._feat then
        return ctx._feat
    end
    local bg = {}
    bg.Root = root(ctx)
    bg.Selected = nil
    bg.Gui = nil
    bg.Basename = basename
    bg.IsImage = isImage
    bg.IsGif = isGif
    bg.Resolve = function(path)
        return M.resolve(ctx, path)
    end
    bg.Tree = function(folder, depth)
        return M.tree(ctx, folder, depth)
    end
    bg.Ensure = function()
        pcall(function()
            if not isfolder(ctx.config.Folder) then
                makefolder(ctx.config.Folder)
            end
            if not isfolder(root(ctx)) then
                makefolder(root(ctx))
            end
        end)
    end
    bg.Apply = function(path)
        if path == "" then
            ctx.set("bg_enabled", false)
            return true
        end
        local ok = M.apply(ctx, path)
        if ok then
            ctx.set("bg_path", path)
            ctx.set("bg_enabled", true)
        end
        return ok
    end
    bg.CloseBrowser = function()
        if bg.Gui then
            pcall(function()
                bg.Gui:Destroy()
            end)
            bg.Gui = nil
        end
    end
    ctx._feat = { Background = bg }
    return ctx._feat
end

function M.openExplorer(ctx)
    local feat = M.feat(ctx)
    local explorer = ctx.modules:require("shared/features/explorer")
    local dominant = ctx.modules:require("shared/ui_theme").make(ctx)
    explorer.open(ctx, feat, dominant)
end

function M.Register(ctx)
    local function reapply()
        if ctx.cfg.bg_enabled then
            M.apply(ctx, ctx.cfg.bg_path)
        end
    end
    ctx.addSetting("bg_enabled", true, function(value)
        if value then
            M.apply(ctx, ctx.cfg.bg_path)
        else
            M.clear(ctx)
        end
    end)
    ctx.addSetting("bg_path", "", function()
        reapply()
    end)
    ctx.addSetting("bg_transparency", 0.45, reapply)
    ctx.addSetting("bg_window_transparency", 0.35, reapply)
    ctx.onUnload(function()
        ctx.stopLoop("background_gif")
    end)
end

function M.Build(tab, ctx)
    local ui = ctx.ui
    ui.section(tab, "sec_background", "Lucide:image")
    ui.toggle(tab, "bg_enabled", "Lucide:image")
    tab:AddParagraph({
        Title = ctx.L("bg_folder_hint"),
        Icon = "Lucide:folder",
        Text = ctx.L("bg_default_note"),
    })
    ui.button(tab, "bg_open_explorer", "Lucide:folder-tree", function()
        M.openExplorer(ctx)
    end)
    ui.button(tab, "bg_default", "Lucide:rotate-ccw", function()
        ctx.set("bg_path", "")
        ctx.set("bg_enabled", true)
        ctx.notify(ctx.L("bg_default_applied"), "success", 3)
    end)
    ui.slider(tab, "bg_transparency", 0, 1, 0.05, "Lucide:blend")
    ui.slider(tab, "bg_window_transparency", 0, 0.8, 0.05, "Lucide:app-window")
    ui.button(tab, "bg_clear", "Lucide:x", function()
        ctx.set("bg_enabled", false)
        ctx.notify(ctx.L("bg_clear"), "info", 2)
    end)
end

return M
end

__EMBED["shared/features/explorer"] = function()
local M = {}

function M.open(ctx, Feat, Dominant)
    local function L(key)
        return ctx.L(key)
    end
    Feat.Background.Ensure()
    Feat.Background.CloseBrowser()

    local TweenService = game:GetService("TweenService")
    local P = Dominant.OphynPalette
    local parent = (typeof(gethui) == "function" and gethui()) or game:GetService("CoreGui")
    local camera = workspace.CurrentCamera
    local viewport = camera and camera.ViewportSize or Vector2.new(1280, 720)
    local W = math.floor(math.min(560, viewport.X - 32))
    local H = math.floor(math.min(430, viewport.Y - 32))
    local state = {
        folder = Feat.Background.Root,
        selected = nil,
        query = "",
        cards = {},
        lastClick = { path = nil, time = 0 },
    }
    local refreshGrid

    local function make(class, props, target)
        local obj = Instance.new(class)
        for key, value in pairs(props or {}) do
            obj[key] = value
        end
        if target then
            obj.Parent = target
        end
        return obj
    end

    local function round(obj, radius, color, transparency)
        make("UICorner", { CornerRadius = UDim.new(0, radius) }, obj)
        if color then
            return make("UIStroke", { Color = color, Transparency = transparency or 0, Thickness = 1 }, obj)
        end
    end

    local function label(target, text, size, color, bold, props)
        local lbl = make("TextLabel", {
            BackgroundTransparency = 1,
            Text = text,
            TextSize = size,
            TextColor3 = color,
            TextXAlignment = Enum.TextXAlignment.Left,
            TextTruncate = Enum.TextTruncate.AtEnd,
        }, target)
        Dominant.StyleFont(lbl, bold)
        for key, value in pairs(props or {}) do
            lbl[key] = value
        end
        return lbl
    end

    local function button(text, target, size, primary)
        local base = primary and P.submitBg or P.btn2
        local btn = make("TextButton", {
            AutoButtonColor = false,
            Text = text,
            TextSize = 12,
            Size = size,
            TextColor3 = primary and P.submitText or P.text,
            BackgroundColor3 = base,
        }, target)
        Dominant.StyleFont(btn, true)
        round(btn, 8, P.stroke, primary and 1 or 0.4)
        btn.MouseEnter:Connect(function()
            local hover = primary and base:Lerp(Color3.new(1, 1, 1), 0.1) or P.btn2Hover
            TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = hover }):Play()
        end)
        btn.MouseLeave:Connect(function()
            TweenService:Create(btn, TweenInfo.new(0.12), { BackgroundColor3 = base }):Play()
        end)
        return btn
    end

    local gui = make("ScreenGui", {
        Name = "DominantBackgroundExplorer",
        ResetOnSpawn = false,
        IgnoreGuiInset = true,
        DisplayOrder = 10050,
        ZIndexBehavior = Enum.ZIndexBehavior.Sibling,
    }, parent)
    Feat.Background.Gui = gui

    local dim = make("TextButton", {
        AutoButtonColor = false,
        Text = "",
        BackgroundColor3 = Color3.new(0, 0, 0),
        BackgroundTransparency = 0.45,
        Size = UDim2.fromScale(1, 1),
    }, gui)

    local win = make("Frame", {
        AnchorPoint = Vector2.new(0.5, 0.5),
        Position = UDim2.fromScale(0.5, 0.5),
        Size = UDim2.fromOffset(W, H),
        BackgroundColor3 = P.card,
        BorderSizePixel = 0,
        ClipsDescendants = true,
    }, gui)
    round(win, 14, P.stroke, 0)
    local scale = make("UIScale", { Scale = 0.94 }, win)
    TweenService:Create(scale, TweenInfo.new(0.25, Enum.EasingStyle.Quint, Enum.EasingDirection.Out), { Scale = 1 }):Play()

    label(win, L("bg_browse"), 15, P.text, true, {
        Position = UDim2.fromOffset(16, 12),
        Size = UDim2.new(1, -64, 0, 20),
    })
    local subtitle = label(win, Feat.Background.Root, 11, P.muted, false, {
        Position = UDim2.fromOffset(16, 32),
        Size = UDim2.new(1, -64, 0, 14),
    })
    local closeBtn = button("×", win, UDim2.fromOffset(30, 30), false)
    closeBtn.Position = UDim2.new(1, -44, 0, 12)
    closeBtn.TextSize = 18

    local backBtn = button(L("bg_back"), win, UDim2.fromOffset(72, 30), false)
    backBtn.Position = UDim2.fromOffset(16, 56)
    local search = make("TextBox", {
        PlaceholderText = L("bg_search"),
        PlaceholderColor3 = P.muted,
        Text = "",
        TextColor3 = P.text,
        TextSize = 12,
        ClearTextOnFocus = false,
        BackgroundColor3 = P.input,
        BorderSizePixel = 0,
        TextXAlignment = Enum.TextXAlignment.Left,
        Position = UDim2.fromOffset(96, 56),
        Size = UDim2.new(1, -204, 0, 30),
    }, win)
    Dominant.StyleFont(search, false)
    round(search, 8, P.stroke, 0.2)
    make("UIPadding", { PaddingLeft = UDim.new(0, 10), PaddingRight = UDim.new(0, 10) }, search)
    local refreshBtn = button(L("bg_refresh"), win, UDim2.fromOffset(84, 30), false)
    refreshBtn.Position = UDim2.new(1, -100, 0, 56)

    local grid = make("ScrollingFrame", {
        BackgroundTransparency = 1,
        BorderSizePixel = 0,
        Position = UDim2.fromOffset(12, 96),
        Size = UDim2.new(1, -24, 1, -152),
        ScrollBarThickness = 3,
        ScrollBarImageColor3 = P.muted,
        AutomaticCanvasSize = Enum.AutomaticSize.Y,
        CanvasSize = UDim2.new(),
    }, win)
    make("UIGridLayout", {
        CellSize = UDim2.fromOffset(120, 104),
        CellPadding = UDim2.fromOffset(10, 10),
        SortOrder = Enum.SortOrder.LayoutOrder,
    }, grid)
    make("UIPadding", { PaddingTop = UDim.new(0, 4), PaddingLeft = UDim.new(0, 4) }, grid)

    local selectedLabel = label(win, L("bg_folder_hint"), 12, P.muted, false, {
        Position = UDim2.new(0, 16, 1, -38),
        Size = UDim2.new(1, -228, 0, 24),
    })
    local clearBtn = button(L("bg_clear"), win, UDim2.fromOffset(84, 30), false)
    clearBtn.Position = UDim2.new(1, -196, 1, -42)
    local applyBtn = button(L("bg_apply"), win, UDim2.fromOffset(96, 30), true)
    applyBtn.Position = UDim2.new(1, -106, 1, -42)

    local function collect()
        local nodes = {}
        local query = string.lower(state.query)
        if query ~= "" then
            for _, node in ipairs(Feat.Background.Tree(Feat.Background.Root, 0)) do
                if node.Kind == "file" and string.find(string.lower(node.Name), query, 1, true) then
                    table.insert(nodes, node)
                end
            end
            return nodes
        end
        local folders, files = {}, {}
        if type(listfiles) == "function" then
            local ok, entries = pcall(listfiles, state.folder)
            if ok and type(entries) == "table" then
                for _, entry in ipairs(entries) do
                    local name = Feat.Background.Basename(entry)
                    local isDir = false
                    if type(isfolder) == "function" then
                        local okDir, result = pcall(isfolder, entry)
                        isDir = okDir and result == true
                    end
                    if isDir then
                        table.insert(folders, { Path = entry, Name = name, Kind = "folder" })
                    elseif Feat.Background.IsImage(entry) then
                        table.insert(files, {
                            Path = entry,
                            Name = name,
                            Kind = "file",
                            Gif = Feat.Background.IsGif(entry),
                        })
                    end
                end
            end
        end
        local function byName(a, b)
            return a.Name:lower() < b.Name:lower()
        end
        table.sort(folders, byName)
        table.sort(files, byName)
        for _, node in ipairs(folders) do
            table.insert(nodes, node)
        end
        for _, node in ipairs(files) do
            table.insert(nodes, node)
        end
        return nodes
    end

    local function setSelectedVisual()
        for path, entry in pairs(state.cards) do
            local on = state.selected ~= nil and state.selected.Path == path
            entry.stroke.Color = on and P.accent or P.stroke
            entry.stroke.Transparency = on and 0 or 0.3
            entry.stroke.Thickness = on and 2 or 1
        end
    end

    local function setSelection(node)
        state.selected = node
        Feat.Background.Selected = node and node.Path or nil
        setSelectedVisual()
        if node and node.Kind == "file" then
            selectedLabel.Text = node.Name .. (node.Gif and "  · GIF" or "")
            selectedLabel.TextColor3 = P.text
        else
            selectedLabel.Text = L("bg_folder_hint")
            selectedLabel.TextColor3 = P.muted
        end
    end

    local function applyNode(node)
        if Feat.Background.Apply(node.Path) then
            Dominant.Notify(L("bg_applied"), "success", 3)
            Feat.Background.CloseBrowser()
        else
            Dominant.Notify(L("bg_failed"), "error", 3)
        end
    end

    local function addCard(node, order)
        local isFolder = node.Kind == "folder"
        local item = make("TextButton", {
            AutoButtonColor = false,
            Text = "",
            BackgroundColor3 = P.input,
            BorderSizePixel = 0,
            LayoutOrder = order,
        }, grid)
        local outline = round(item, 10, P.stroke, 0.3)
        if isFolder then
            label(item, "▸", 26, P.muted, true, {
                Position = UDim2.fromOffset(0, 10),
                Size = UDim2.new(1, 0, 0, 56),
                TextXAlignment = Enum.TextXAlignment.Center,
            })
        else
            local thumb = make("ImageLabel", {
                BackgroundTransparency = 1,
                BorderSizePixel = 0,
                Position = UDim2.fromOffset(4, 4),
                Size = UDim2.new(1, -8, 0, 70),
                ScaleType = Enum.ScaleType.Crop,
                Image = Feat.Background.Resolve(node.Path) or "",
            }, item)
            round(thumb, 8)
            if node.Gif then
                local badge = label(item, "GIF", 9, P.submitText, true, {
                    BackgroundColor3 = P.submitBg,
                    BackgroundTransparency = 0,
                    Position = UDim2.new(1, -38, 0, 8),
                    Size = UDim2.fromOffset(30, 16),
                    TextXAlignment = Enum.TextXAlignment.Center,
                })
                round(badge, 5)
            end
        end
        label(item, node.Name, 11, isFolder and P.muted or P.text, false, {
            Position = UDim2.new(0, 8, 1, -26),
            Size = UDim2.new(1, -16, 0, 20),
        })
        state.cards[node.Path] = { frame = item, stroke = outline }
        item.MouseEnter:Connect(function()
            TweenService:Create(item, TweenInfo.new(0.12), { BackgroundColor3 = P.btn2 }):Play()
        end)
        item.MouseLeave:Connect(function()
            TweenService:Create(item, TweenInfo.new(0.12), { BackgroundColor3 = P.input }):Play()
        end)
        item.MouseButton1Click:Connect(function()
            if isFolder then
                state.folder = node.Path
                state.query = ""
                search.Text = ""
                setSelection(nil)
                refreshGrid()
                return
            end
            local now = os.clock()
            if state.lastClick.path == node.Path and now - state.lastClick.time < 0.4 then
                applyNode(node)
                return
            end
            state.lastClick = { path = node.Path, time = now }
            setSelection(node)
        end)
    end

    refreshGrid = function()
        for _, child in ipairs(grid:GetChildren()) do
            if child:IsA("GuiObject") then
                child:Destroy()
            end
        end
        state.cards = {}
        local nodes = collect()
        subtitle.Text = state.query ~= "" and (L("bg_search") .. ": " .. state.query) or state.folder
        local atRoot = state.folder == Feat.Background.Root and state.query == ""
        backBtn.TextTransparency = atRoot and 0.55 or 0
        if #nodes == 0 then
            label(grid, L("bg_no_files"), 12, P.muted, false, {
                Size = UDim2.new(1, -8, 0, 40),
                TextWrapped = true,
                TextXAlignment = Enum.TextXAlignment.Center,
            })
        else
            for index, node in ipairs(nodes) do
                addCard(node, index)
            end
        end
        setSelectedVisual()
    end

    search:GetPropertyChangedSignal("Text"):Connect(function()
        if search.Text ~= state.query then
            state.query = search.Text
            refreshGrid()
        end
    end)

    backBtn.MouseButton1Click:Connect(function()
        if state.query ~= "" then
            state.query = ""
            search.Text = ""
        elseif state.folder ~= Feat.Background.Root then
            local up = state.folder:match("^(.*)/[^/]+$")
            state.folder = (up and #up >= #Feat.Background.Root) and up or Feat.Background.Root
        else
            return
        end
        refreshGrid()
    end)

    refreshBtn.MouseButton1Click:Connect(function()
        Feat.Background.Ensure()
        refreshGrid()
        Dominant.Notify(L("bg_refresh"), "info", 2)
    end)

    clearBtn.MouseButton1Click:Connect(function()
        Feat.Background.Apply("")
        setSelection(nil)
        Dominant.Notify(L("bg_clear"), "info", 2)
    end)

    applyBtn.MouseButton1Click:Connect(function()
        if not state.selected or state.selected.Kind ~= "file" then
            Dominant.Notify(L("bg_no_files"), "warning", 3)
            return
        end
        applyNode(state.selected)
    end)

    dim.MouseButton1Click:Connect(Feat.Background.CloseBrowser)
    closeBtn.MouseButton1Click:Connect(Feat.Background.CloseBrowser)

    local preset = Feat.Background.Selected
    if preset then
        local presetFolder = preset:match("^(.*)/[^/]+$")
        if presetFolder and #presetFolder >= #Feat.Background.Root then
            state.folder = presetFolder
        end
    end
    refreshGrid()
    if preset then
        for _, node in ipairs(collect()) do
            if node.Path == preset then
                setSelection(node)
                break
            end
        end
    end
end

return M
end

__EMBED["shared/features/misc"] = function()
local Players = game:GetService("Players")
local GuiService = game:GetService("GuiService")
local HttpService = game:GetService("HttpService")
local TeleportService = game:GetService("TeleportService")

local LocalPlayer = Players.LocalPlayer

local M = {}

function M.Register(ctx, data)
    local function rejoin()
        ctx.notify(ctx.L("n_rejoining"), "info", 3)
        pcall(function()
            if #Players:GetPlayers() <= 1 then
                LocalPlayer:Kick("\nRejoining")
                task.wait()
                TeleportService:Teleport(game.PlaceId, LocalPlayer)
            else
                TeleportService:TeleportToPlaceInstance(game.PlaceId, game.JobId, LocalPlayer)
            end
        end)
    end

    local function serverHop()
        task.spawn(function()
            local url = string.format("https://games.roblox.com/v1/games/%d/servers/Public?sortOrder=Asc&limit=100", game.PlaceId)
            local okFetch, body = pcall(function()
                return game:HttpGet(url)
            end)
            local choices = {}
            if okFetch then
                local okDecode, decoded = pcall(function()
                    return HttpService:JSONDecode(body)
                end)
                if okDecode and type(decoded) == "table" and type(decoded.data) == "table" then
                    for _, server in ipairs(decoded.data) do
                        if server.id ~= game.JobId and server.playing and server.maxPlayers and server.playing < server.maxPlayers - 1 then
                            table.insert(choices, server.id)
                        end
                    end
                end
            end
            if #choices == 0 then
                ctx.notify(ctx.L("n_no_servers"), "warning", 4)
                return
            end
            ctx.notify(ctx.L("n_hopping"), "info", 3)
            pcall(function()
                TeleportService:TeleportToPlaceInstance(game.PlaceId, choices[math.random(1, #choices)], LocalPlayer)
            end)
        end)
    end

    ctx.addSetting("anti_afk", true, function(value)
        if value then
            ctx.bind("antiafk", LocalPlayer.Idled, function()
                pcall(function()
                    local virtualUser = game:GetService("VirtualUser")
                    virtualUser:CaptureController()
                    virtualUser:ClickButton2(Vector2.new())
                end)
            end)
        else
            ctx.unbind("antiafk")
        end
    end)
    ctx.addSetting("auto_rejoin", true, function(value)
        if value then
            ctx.bind("autorejoin", GuiService.ErrorMessageChanged, function(message)
                if message and message ~= "" and not ctx.state.unloading then
                    rejoin()
                end
            end)
        else
            ctx.unbind("autorejoin")
        end
    end)

    M.rejoin = rejoin
    M.serverHop = serverHop

    ctx.addHotkey("key_esp", "hotkey_esp", function()
        ctx.set("esp", not ctx.cfg.esp)
    end)
    ctx.addHotkey("key_panic", "hotkey_panic", function()
        for key, default in pairs(ctx.defaults) do
            if type(default) == "boolean" and ctx.cfg[key] == true and ctx.hooks[key] then
                ctx.set(key, false)
            end
        end
        ctx.notify(ctx.L("n_panic"), "warning", 2)
    end)
end

function M.Build(tab, ctx, data)
    ctx.modules:require("shared/features/scripts").Build(tab, ctx)
    local ui = ctx.ui
    ui.section(tab, "sec_utility", "Lucide:wrench")
    ui.toggle(tab, "anti_afk", "Lucide:timer")
    ui.toggle(tab, "auto_rejoin", "Lucide:power")
    ui.button(tab, "btn_reset_char", "Lucide:rotate-ccw", function()
        local humanoid = ctx.state.humanoid
        if humanoid then
            humanoid.Health = 0
        end
    end)

    ui.section(tab, "sec_server", "Lucide:server")
    ui.button(tab, "btn_rejoin", "Lucide:refresh-cw", function()
        M.rejoin()
    end)
    ui.button(tab, "btn_serverhop", "Lucide:log-out", function()
        M.serverHop()
    end)
    ui.button(tab, "btn_copy_jobid", "Lucide:copy", function()
        ctx.copy(game.JobId)
    end)
    ui.button(tab, "btn_copy_join", "Lucide:copy", function()
        ctx.copy(string.format("game:GetService('TeleportService'):TeleportToPlaceInstance(%d, '%s', game.Players.LocalPlayer)", game.PlaceId, game.JobId))
    end)
end

return M
end

__EMBED["shared/features/movement"] = function()
local Players = game:GetService("Players")
local RunService = game:GetService("RunService")
local UserInputService = game:GetService("UserInputService")

local LocalPlayer = Players.LocalPlayer

local M = {}

function M.Register(ctx, data)
    local fly = { velocity = nil, gyro = nil }
    local noclipChanged = {}
    local anchor = nil

    local function cframeStep(dt)
        local root, humanoid = ctx.state.root, ctx.state.humanoid
        if not root or not humanoid or ctx.cfg.fly then
            return
        end
        local move = humanoid.MoveDirection
        if move.Magnitude > 0 then
            local speed = math.max(1, tonumber(ctx.cfg.cframe_speed_value) or 16)
            root.CFrame = root.CFrame + move.Unit * (speed * dt)
        end
    end

    local function applyJump()
        local humanoid = ctx.state.humanoid
        if humanoid and ctx.cfg.jumppower_on then
            humanoid.UseJumpPower = true
            humanoid.JumpPower = ctx.cfg.jumppower
        end
    end

    local function stopFly()
        ctx.unbind("fly")
        if fly.velocity then
            fly.velocity:Destroy()
            fly.velocity = nil
        end
        if fly.gyro then
            fly.gyro:Destroy()
            fly.gyro = nil
        end
        local humanoid = ctx.state.humanoid
        if humanoid then
            humanoid.PlatformStand = false
        end
    end

    local function startFly()
        stopFly()
        local root, humanoid = ctx.state.root, ctx.state.humanoid
        if not root or not humanoid then
            return
        end
        local velocity = Instance.new("BodyVelocity")
        velocity.MaxForce = Vector3.new(9e9, 9e9, 9e9)
        velocity.Velocity = Vector3.zero
        velocity.Parent = root

        local gyro = Instance.new("BodyGyro")
        gyro.MaxTorque = Vector3.new(9e9, 9e9, 9e9)
        gyro.P = 9e4
        gyro.CFrame = root.CFrame
        gyro.Parent = root

        fly.velocity = velocity
        fly.gyro = gyro
        humanoid.PlatformStand = true

        ctx.bind("fly", RunService.RenderStepped, function()
            local camera = workspace.CurrentCamera
            if not camera or not velocity.Parent then
                return
            end
            local look = camera.CFrame.LookVector
            local right = camera.CFrame.RightVector
            local direction = Vector3.zero
            if UserInputService:IsKeyDown(Enum.KeyCode.W) then
                direction += look
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.S) then
                direction -= look
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.D) then
                direction += right
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.A) then
                direction -= right
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.Space) then
                direction += Vector3.yAxis
            end
            if UserInputService:IsKeyDown(Enum.KeyCode.LeftShift) then
                direction -= Vector3.yAxis
            end
            local move = humanoid.MoveDirection
            if direction.Magnitude == 0 and move.Magnitude > 0 then
                direction = move
            end
            if direction.Magnitude > 0 then
                direction = direction.Unit
            end
            velocity.Velocity = direction * ctx.cfg.fly_speed
            gyro.CFrame = camera.CFrame
        end)
    end

    local function noclipStep()
        local character = ctx.state.character
        if not character then
            return
        end
        for _, part in ipairs(character:GetDescendants()) do
            if part:IsA("BasePart") and part.CanCollide then
                if noclipChanged[part] == nil then
                    noclipChanged[part] = true
                end
                part.CanCollide = false
            end
        end
    end

    local function restoreNoclip()
        for part, original in pairs(noclipChanged) do
            if part.Parent then
                part.CanCollide = original
            end
        end
        noclipChanged = {}
    end

    local function ghostStep()
        for _, player in ipairs(Players:GetPlayers()) do
            local character = player.Character
            if player ~= LocalPlayer and character then
                for _, part in ipairs(character:GetDescendants()) do
                    if part:IsA("BasePart") and part.CanCollide then
                        part.CanCollide = false
                    end
                end
            end
        end
    end

    local function speedBoost(dt)
        local root, humanoid = ctx.state.root, ctx.state.humanoid
        if not root or not humanoid then
            return
        end
        local boost = tonumber(ctx.cfg.speed_boost) or 0
        local move = humanoid.MoveDirection
        if boost > 0 and move.Magnitude > 0 then
            root.CFrame = root.CFrame + move * (boost * 60 * dt / 10)
        end
    end

    local function nearestRoot(farthest)
        local root = ctx.state.root
        if not root then
            return nil
        end
        local best, bestDistance = nil, farthest and -math.huge or math.huge
        for _, player in ipairs(Players:GetPlayers()) do
            local character = player.Character
            local part = player ~= LocalPlayer and character and character:FindFirstChild("HumanoidRootPart")
            if part then
                local distance = (part.Position - root.Position).Magnitude
                if (farthest and distance > bestDistance) or (not farthest and distance < bestDistance) then
                    best, bestDistance = part, distance
                end
            end
        end
        return best
    end

    local function teleport(farthest)
        local target = nearestRoot(farthest)
        local root = ctx.state.root
        if not target or not root then
            ctx.notify(ctx.L("n_no_player"), "warning", 3)
            return
        end
        root.CFrame = target.CFrame
    end

    ctx.addSetting("cframe_speed", false, function(value)
        if value then
            ctx.bind("cframe", RunService.Heartbeat, cframeStep)
        else
            ctx.unbind("cframe")
        end
    end)
    ctx.addSetting("cframe_speed_value", 50)
    ctx.addSetting("jumppower_on", false, function(value)
        if value then
            ctx.bind("jump", RunService.Heartbeat, applyJump)
        else
            ctx.unbind("jump")
        end
    end)
    ctx.addSetting("jumppower", 50, function()
        applyJump()
    end)
    ctx.addSetting("infinite_jump", false, function(value)
        if value then
            ctx.bind("infjump", UserInputService.JumpRequest, function()
                local humanoid = ctx.state.humanoid
                if humanoid and ctx.cfg.infinite_jump then
                    humanoid:ChangeState(Enum.HumanoidStateType.Jumping)
                end
            end)
        else
            ctx.unbind("infjump")
        end
    end)
    ctx.addSetting("noclip", false, function(value)
        if value then
            ctx.bind("noclip", RunService.Stepped, noclipStep)
        else
            ctx.unbind("noclip")
            restoreNoclip()
        end
    end)
    ctx.addSetting("fly", false, function(value)
        if value then
            startFly()
        else
            stopFly()
        end
    end)
    ctx.addSetting("fly_speed", 60)
    ctx.addSetting("speed_boost_on", false, function(value)
        if value then
            ctx.bind("speedboost", RunService.Heartbeat, speedBoost)
        else
            ctx.unbind("speedboost")
        end
    end)
    ctx.addSetting("speed_boost", 0)
    ctx.addSetting("ghost_players", false, function(value)
        if value then
            ctx.bind("ghost", RunService.Stepped, ghostStep)
        else
            ctx.unbind("ghost")
        end
    end)

    if ctx.gameOptions == nil or ctx.gameOptions.builtInFly ~= false then
        ctx.addHotkey("key_fly", "hotkey_fly", function()
            ctx.set("fly", not ctx.cfg.fly)
        end)
    end
    ctx.addHotkey("key_noclip", "hotkey_noclip", function()
        ctx.set("noclip", not ctx.cfg.noclip)
    end)

    M.teleport = teleport
    M.dropAnchor = function()
        local root = ctx.state.root
        if root then
            anchor = root.CFrame
            ctx.notify(ctx.L("n_anchor_set"), "success", 3)
        end
    end
    M.beamUp = function()
        local root = ctx.state.root
        if not root then
            return
        end
        if not anchor then
            ctx.notify(ctx.L("n_no_anchor"), "warning", 3)
            return
        end
        root.CFrame = anchor
    end

    ctx.onUnload(function()
        stopFly()
        restoreNoclip()
    end)
end

function M.Build(tab, ctx, data)
    local ui = ctx.ui
    ui.section(tab, "sec_speed", "Lucide:gauge")
    ui.toggle(tab, "cframe_speed", "Lucide:gauge")
    ui.number(tab, "cframe_speed_value", "Lucide:gauge", 1)
    ui.toggle(tab, "speed_boost_on", "Lucide:zap")
    ui.slider(tab, "speed_boost", 0, 20, 0.25, "Lucide:gauge", " boost")

    ui.section(tab, "sec_jump", "Lucide:arrow-up")
    ui.toggle(tab, "jumppower_on", "Lucide:arrow-up")
    ui.slider(tab, "jumppower", 0, 200, 5, "Lucide:arrow-up")
    ui.toggle(tab, "infinite_jump", "Lucide:chevrons-up")

    ui.section(tab, "sec_collision", "Lucide:ghost")
    ui.toggle(tab, "noclip", "Lucide:ghost")
    ui.toggle(tab, "ghost_players", "Lucide:users")

    if ctx.gameOptions == nil or ctx.gameOptions.builtInFly ~= false then
        ui.section(tab, "sec_flight", "Lucide:plane")
        ui.toggle(tab, "fly", "Lucide:plane")
        ui.slider(tab, "fly_speed", 10, 300, 5, "Lucide:wind")
    end

    ui.section(tab, "sec_teleport", "Lucide:navigation")
    ui.button(tab, "btn_tp_nearest", "Lucide:navigation", function()
        M.teleport(false)
    end)
    ui.button(tab, "btn_tp_farthest", "Lucide:navigation", function()
        M.teleport(true)
    end)
    ui.button(tab, "btn_anchor_drop", "Lucide:anchor", function()
        M.dropAnchor()
    end)
    ui.button(tab, "btn_anchor_beam", "Lucide:arrow-up-from-line", function()
        M.beamUp()
    end)
end

return M
end

__EMBED["shared/features/screen"] = function()
local Lighting = game:GetService("Lighting")
local RunService = game:GetService("RunService")
local Players = game:GetService("Players")

local LocalPlayer = Players.LocalPlayer

local M = {}

function M.Register(ctx, data)
    local savedLight = nil
    local savedFog = nil
    local savedAtmospheres = {}
    local savedFov = nil
    local savedZoom = nil

    local function restoreProps(saved)
        if not saved then
            return
        end
        for key, value in pairs(saved) do
            pcall(function()
                Lighting[key] = value
            end)
        end
    end

    local function fullbrightStep()
        Lighting.Brightness = 2
        Lighting.ClockTime = 14
        Lighting.GlobalShadows = false
        Lighting.Ambient = Color3.fromRGB(190, 190, 190)
        Lighting.OutdoorAmbient = Color3.fromRGB(190, 190, 190)
    end

    local function noFogStep()
        Lighting.FogStart = 1e9
        Lighting.FogEnd = 1e9
        for _, atmosphere in ipairs(Lighting:GetChildren()) do
            if atmosphere:IsA("Atmosphere") then
                if savedAtmospheres[atmosphere] == nil then
                    savedAtmospheres[atmosphere] = atmosphere.Density
                end
                atmosphere.Density = 0
            end
        end
    end

    local function thirdPersonStep()
        local distance = math.max(0.5, tonumber(ctx.cfg.third_person_dist) or 10)
        pcall(function()
            LocalPlayer.CameraMaxZoomDistance = distance
            LocalPlayer.CameraMinZoomDistance = distance
        end)
    end

    ctx.addSetting("fullbright", false, function(value)
        if value then
            savedLight = savedLight or {
                Brightness = Lighting.Brightness,
                ClockTime = Lighting.ClockTime,
                GlobalShadows = Lighting.GlobalShadows,
                Ambient = Lighting.Ambient,
                OutdoorAmbient = Lighting.OutdoorAmbient,
            }
            ctx.startLoop("fullbright", 0.25, fullbrightStep)
        else
            ctx.stopLoop("fullbright")
            restoreProps(savedLight)
            savedLight = nil
        end
    end)
    ctx.addSetting("no_fog", false, function(value)
        if value then
            savedFog = savedFog or { FogStart = Lighting.FogStart, FogEnd = Lighting.FogEnd }
            ctx.startLoop("nofog", 0.5, noFogStep)
        else
            ctx.stopLoop("nofog")
            restoreProps(savedFog)
            savedFog = nil
            for atmosphere, density in pairs(savedAtmospheres) do
                pcall(function()
                    if atmosphere.Parent then
                        atmosphere.Density = density
                    end
                end)
            end
            savedAtmospheres = {}
        end
    end)
    ctx.addSetting("fov_on", false, function(value)
        if value then
            local camera = workspace.CurrentCamera
            if camera and savedFov == nil then
                savedFov = camera.FieldOfView
            end
            ctx.bind("fov", RunService.RenderStepped, function()
                local current = workspace.CurrentCamera
                if current then
                    current.FieldOfView = ctx.cfg.fov
                end
            end)
        else
            ctx.unbind("fov")
            local current = workspace.CurrentCamera
            if current and savedFov then
                current.FieldOfView = savedFov
            end
            savedFov = nil
        end
    end)
    ctx.addSetting("fov", 90)
    ctx.addSetting("third_person", false, function(value)
        if value then
            savedZoom = savedZoom or { min = LocalPlayer.CameraMinZoomDistance, max = LocalPlayer.CameraMaxZoomDistance }
            thirdPersonStep()
            ctx.startLoop("thirdperson", 0.5, thirdPersonStep)
        else
            ctx.stopLoop("thirdperson")
            if savedZoom then
                pcall(function()
                    LocalPlayer.CameraMaxZoomDistance = savedZoom.max
                    LocalPlayer.CameraMinZoomDistance = savedZoom.min
                end)
            end
            savedZoom = nil
        end
    end)
    ctx.addSetting("third_person_dist", 10, function()
        if ctx.cfg.third_person then
            thirdPersonStep()
        end
    end)

    ctx.onUnload(function()
        restoreProps(savedLight)
        restoreProps(savedFog)
    end)
end

function M.Build(tab, ctx, data)
    local ui = ctx.ui
    ui.section(tab, "sec_lighting", "Lucide:sun")
    ui.toggle(tab, "fullbright", "Lucide:sun")
    ui.toggle(tab, "no_fog", "Lucide:cloud")

    ui.section(tab, "sec_camera", "Lucide:camera")
    ui.toggle(tab, "fov_on", "Lucide:scan")
    ui.slider(tab, "fov", 40, 120, 1, "Lucide:scan")
    ui.toggle(tab, "third_person", "Lucide:camera")
    ui.slider(tab, "third_person_dist", 2, 60, 1, "Lucide:ruler", " studs")
end

return M
end

__EMBED["shared/features/scripts"] = function()
local M = {}

local function localFolder(ctx)
    return ctx.config.Folder .. "/misc"
end

local function ensureFolders(ctx)
    pcall(function()
        if not isfolder(ctx.config.Folder) then
            makefolder(ctx.config.Folder)
        end
        if not isfolder(localFolder(ctx)) then
            makefolder(localFolder(ctx))
        end
    end)
end

local function fetchIndex(ctx)
    local ok, body = pcall(game.HttpGet, game, ctx.modules.base .. "scripts/index.lua")
    if not ok or type(body) ~= "string" or #body < 5 then
        return nil
    end
    local chunk = loadstring(body)
    if not chunk then
        return nil
    end
    local okRun, index = pcall(chunk)
    if okRun and type(index) == "table" then
        return index
    end
    return nil
end

local function runSource(ctx, source, name)
    local chunk, compileError = loadstring(source, "=" .. name)
    if not chunk then
        ctx.warn(tostring(compileError))
        ctx.notify(ctx.L("script_failed") .. " " .. name, "error", 5)
        return
    end
    local ok, err = pcall(chunk)
    if ok then
        ctx.notify(ctx.L("script_ran") .. " " .. name, "success", 3)
    else
        ctx.warn(tostring(err))
        ctx.notify(ctx.L("script_failed") .. " " .. name, "error", 5)
    end
end

local function listLocal(ctx)
    local files = {}
    if not ctx.caps.files or type(listfiles) ~= "function" then
        return files
    end
    local ok, entries = pcall(listfiles, localFolder(ctx))
    if not ok or type(entries) ~= "table" then
        return files
    end
    for _, entry in ipairs(entries) do
        local name = tostring(entry):gsub("\\", "/"):match("([^/]+)$") or tostring(entry)
        local lower = name:lower()
        if lower:match("%.lua$") or lower:match("%.txt$") then
            table.insert(files, { name = name, path = localFolder(ctx) .. "/" .. name })
        end
    end
    table.sort(files, function(a, b)
        return a.name:lower() < b.name:lower()
    end)
    return files
end

function M.Build(tab, ctx)
    ctx.ui.section(tab, "sec_scripts", "Lucide:file-code")
    ensureFolders(ctx)

    local index = fetchIndex(ctx)
    if index then
        for _, entry in ipairs(index) do
            tab:AddButton({
                Text = tostring(entry.name or entry.file),
                Description = tostring(entry.desc or ctx.L("btn_run_script")),
                Icon = "Lucide:download",
                Callback = function()
                    local okGet, source = pcall(game.HttpGet, game, ctx.modules.base .. "scripts/" .. tostring(entry.file))
                    if not okGet or type(source) ~= "string" then
                        ctx.notify(ctx.L("script_failed") .. " " .. tostring(entry.name), "error", 4)
                        return
                    end
                    pcall(writefile, localFolder(ctx) .. "/" .. tostring(entry.file), source)
                    runSource(ctx, source, tostring(entry.name))
                end,
            })
        end
    else
        tab:AddParagraph({ Title = ctx.L("scripts_offline"), Icon = "Lucide:wifi-off", Text = ctx.L("scripts_hint") })
    end

    for _, file in ipairs(listLocal(ctx)) do
        tab:AddButton({
            Text = file.name,
            Description = ctx.L("scripts_local"),
            Icon = "Lucide:play",
            Callback = function()
                local okRead, source = pcall(readfile, file.path)
                if okRead and type(source) == "string" then
                    runSource(ctx, source, file.name)
                end
            end,
        })
    end
end

return M
end

