            BackgroundTransparency = 1,
            FontFace = fontOf(bold and Enum.FontWeight.Bold or Enum.FontWeight.Regular),
            TextSize = size,
            TextColor3 = color,
            TextTransparency = 1,
            TextXAlignment = Enum.TextXAlignment.Left,
